window.kbPageData["views/entry/k-6abee2c045f03a32"] = {"key":"entry/k-6abee2c045f03a32","state":{"route":"entry/k-6abee2c045f03a32"},"node":{"id":"k-6abee2c045f03a32","mode":"k","title":"合作工程的工作总量","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["合作工程总量等于各队效率与实际工作时间乘积之和"],"qs":["江苏 2023 B类 行测#61"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"各队工作效率恒定且完成的工作量可以相加时，工程总量等于各队工作效率与各自实际工作时间的乘积之和。按周期轮休时，休息日不计入实际工作时间。","review":{"definition":"各队工作效率恒定且完成的工作量可以相加时，工程总量等于各队工作效率与各自实际工作时间的乘积之和。按周期轮休时，休息日不计入实际工作时间。","explanation":"按各队从开始工作起的轮休周期折算，甲先开工时，甲、乙分别实际工作18天和15天。乙先开工时，两队分别实际工作12天和20天。同一工程总量相等，因此甲、乙的日工作效率之比为5∶6。取甲每天完成5份、乙每天完成6份，总工程量为180份，甲独做须实际工作36天。完成前经历11个工作3天、休息1天的完整周期，最后再工作3天即完工，共47天，选C。","references":[],"evidence":"18甲+15乙=12甲+20乙","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#61":{"paper":"江苏 2023 B类 行测","n":61,"mod":"数量关系","src":["22262c34d18cd68fbee4.pdf",10],"asrc":["b08f2713d73015eac675.pdf",19],"card":"1193f019bef5c21aeb3b0246","links":[{"id":"k-6abee2c045f03a32","role":"解题依据","why":"工程量由各队实际工作期间完成的工程量相加得到。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6abee2c045f03a32":[["江苏 2023 B类 行测#61"]]}};
